struct Node;

/// Percent-encode a value for use in a URL query component (RFC 3986 unreserved
/// characters pass through; everything else is encoded), so untrusted input
/// cannot alter the structure of the URL.
fn encode_query(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment lookup, performed on every call. Its result is deliberately
        // not used, so the report below is the same with or without it.
        // Transport failures come back as values and are ignored; out-of-allowlist
        // requests trap at the boundary.
        // PublishedDigest has no free-text field, so the query text is the
        // considered ids joined by spaces.
        let text = published.considered.join(" ");
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(&text)
        );
        let _enrichment = crate::aap::caps::http_client::fetch(&url);

        let mut recorded: u32 = 0;

        for id in &published.considered {
            if id.is_empty() {
                continue;
            }
            crate::aap::caps::state_rw::put(id, &published.date);
            recorded = recorded.saturating_add(1);
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
